action.code:
# Collect all unique song IDs
unique_songs = set()

# Add liked songs
if liked_songs and 'items' in liked_songs:
    for item in liked_songs['items']:
        if item and 'track' in item and item['track'] and 'id' in item['track']:
            unique_songs.add(item['track']['id'])

# Add songs from saved albums
if saved_albums and 'items' in saved_albums:
    for album in saved_albums['items']:
        if album and 'album' in album:
            album_id = album['album']['id']
            album_tracks = apis.spotify.get_album_tracks(album_id=album_id, access_token=token)
            if album_tracks and 'items' in album_tracks:
                for track in album_tracks['items']:
                    if track and 'id' in track:
                        unique_songs.add(track['id'])

# Add songs from all playlists
if playlists and 'items' in playlists:
    for playlist in playlists['items']:
        if playlist and 'id' in playlist:
            playlist_id = playlist['id']
            playlist_tracks = apis.spotify.get_playlist_tracks(playlist_id=playlist_id, access_token=token)
            if playlist_tracks and 'items' in playlist_tracks:
                for item in playlist_tracks['items']:
                    if item and 'track' in item and item['track'] and 'id' in item['track']:
                        unique_songs.add(item['track']['id'])

print(f"Total unique songs: {len(unique_songs)}")
</parameter>
