action.code:
# Collect all pending requests from 50+ days across all pages
all_pages = [sent_requests, sent_requests_page2, sent_requests_page3, sent_requests_page4, sent_requests_page5, sent_requests_page6]

pending_50_plus = []
for page in all_pages:
    for req in page:
        if req['approved_at'] is None and req['denied_at'] is None:
            created_at = datetime.fromisoformat(req['created_at'])
            days_pending = (current_time - created_at).days
            if days_pending >= 50:
                pending_50_plus.append(req)

print(f"Found {len(pending_50_plus)} pending requests for 50+ days:")
for req in pending_50_plus:
    created_at = datetime.fromisoformat(req['created_at'])
    days_pending = (current_time - created_at).days
    print(f"  ID {req['payment_request_id']}: {req['description']} ({days_pending} days) to {req['receiver']['name']}")

