action.code:
# Collect all song IDs from liked songs, albums, and playlists
all_song_ids = set()

# From liked songs
for song in liked_songs:
    all_song_ids.add(song['song_id'])

# From liked albums
for album in liked_albums:
    for song_id in album['song_ids']:
        all_song_ids.add(song_id)

# From playlists
for playlist in playlists:
    for song_id in playlist['song_ids']:
        all_song_ids.add(song_id)

print(f"Total unique song IDs: {len(all_song_ids)}")
print(f"Song IDs: {sorted(all_song_ids)[:20]}")  # Print first 20

# Get details for each song to check genre and play count
song_details = {}
for song_id in sorted(all_song_ids):
    song_info = apis.spotify.show_song(access_token=token, song_id=song_id)
    song_details[song_id] = song_info
    print(f"Song {song_id}: {song_info.get('title')} - Genre: {song_info.get('genre')} - Play Count: {song_info.get('play_count', 0)}")

# Filter for indie songs and sort by play count
indie_songs = []
for song_id, song_info in song_details.items():
    if song_info.get('genre') == 'indie':
        indie_songs.append({
            'title': song_info['title'],
            'play_count': song_info.get('play_count', 0)
        })

# Sort by play count descending
indie_songs.sort(key=lambda x: x['play_count'], reverse=True)

print("Indie songs sorted by play count:")
for song in indie_songs:
    print(f"{song['title']} - Play Count: {song['play_count']}")

# Get top 3
top_3 = indie_songs[:3]
print(f"\nTop 3 indie songs: {[s['title'] for s in top_3]}")

# Get account passwords for login
pw = {p['account_name']: p['password'] for p in apis.supervisor.show_account_passwords()}
print(pw)

