# Compile all indie songs from all sources (library, liked, playlists)
all_indie_songs = []

# From song library
for song in song_details:
    if song.get('genre') == 'indie':
        all_indie_songs.append({
            'title': song['title'],
            'play_count': song.get('play_count', 0)
        })

# From liked songs
for song in liked_song_details:
    if song.get('genre') == 'indie':
        all_indie_songs.append({
            'title': song['title'],
            'play_count': song.get('play_count', 0)
        })

# From playlist songs
for song in all_playlist_songs:
    if song.get('genre') == 'indie':
        all_indie_songs.append({
            'title': song['title'],
            'play_count': song.get('play_count', 0)
        })

# Remove duplicates and sort by play count
unique_indie = {song['title']: song['play_count'] for song in all_indie_songs}
sorted_indie = sorted(unique_indie.items(), key=lambda x: x[1], reverse=True)

print("All indie songs sorted by play count:")
for title, plays in sorted_indie:
    print(f"- {title}: {plays} plays")

# Get top 3
top_3 = sorted_indie[:3]
result = ', '.join([title for title, _ in top_3])
print(f"\nTop 3 most played indie songs: {result}")
